{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Labetalol, which shares an aromatic carboxamide and secondary amine with the query, had an absolute oral bioavailability of 28% (19-49%) in subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In five healthy subjects, labetalol systemic bioavailability was 30 ± 3% after oral administration, again above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "L-5-hydroxytryptophan, an indole-containing small molecule, had an absolute bioavailability of 49% in volunteers, supporting high oral bioavailability for indole-based structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "AZD0837, a small-molecule drug with amide/amidoxime and aromatic heterocycle features, had an absolute bioavailability of 22–52% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "PF-05241328, an oral small molecule with an aromatic sulfonamide, had an absolute bioavailability of 38% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Isradipine, a structurally different dihydropyridine, had a systemic availability of 16.5% in healthy volunteers, below the threshold; however, it lacks the carboxamide/secondary-amine motif of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "One labetalol study reported about 18% systemic availability in fasted subjects, below threshold, indicating first-pass variability; other labetalol studies are above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of highly transferable experimental evidence, especially labetalol (arylcarboxamide/secondary amine; F ~26-33%) and other small-molecule drugs with F 22-100%, supports F ≥ 20%; the few sub-20% records come from structurally less relevant or variable first-pass settings, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule was retrieved.",
    "The query's F may be near the 20% threshold; formulation and first-pass variability could affect classification.",
    "Some retrieved records (e.g., pramipexole, vitamin D analogue) have SMILES that do not match the reported drug names, limiting their use."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

